import createMiddleware from "next-intl/middleware"
import { NextResponse, type NextRequest } from "next/server"
import { routing } from "./src/i18n/routing"
// Generated by scripts/build-program-ids.mjs from public/mock/programs-by-id (--check guards drift).
import programIds from "./src/lib/program-ids.json"

const intlMiddleware = createMiddleware(routing)

// ISR guard (v2.54): only snapshot ids reach the on-demand ISR program page. Any
// other `/<locale>/programs/<x>` (not a GUID, unknown, dotted, `%2F`, other letter
// case) is answered here, before routing, so no bad path ever writes a cache entry.
const PROGRAM_IDS = new Set<string>(programIds)
const PROGRAM_PATH = /^\/([^/]+)\/programs\/(.+)$/
const LOCALES: readonly string[] = routing.locales

// `locale` is one of routing.locales; nothing from the URL is echoed into the body.
const programNotFound = (locale: string) =>
    new NextResponse(
        `<!DOCTYPE html><html lang="${locale}"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta name="viewport" content="width=device-width, initial-scale=1"><title>404 · Tedo</title></head>` +
            `<body style="font-family:system-ui,sans-serif;text-align:center;padding:4rem 1rem"><h1>404</h1><p><a href="/${locale}">Tedo</a></p></body></html>`,
        {
            status: 404,
            headers: {
                "content-type": "text/html; charset=utf-8",
                "cache-control": "no-store",
                "x-robots-tag": "noindex",
            },
        }
    )

export default function proxy(request: NextRequest) {
    const program = PROGRAM_PATH.exec(request.nextUrl.pathname)
    if (program && LOCALES.includes(program[1]) && !PROGRAM_IDS.has(program[2])) {
        return programNotFound(program[1])
    }

    const response = intlMiddleware(request)

    const location = response.headers.get("location")
    if (location) {
        try {
            const url = new URL(location)
            const forwardedHost = (
                request.headers.get("x-forwarded-host") ||
                request.headers.get("host") ||
                url.host
            )
                .split(",")[0]
                .trim()
            const hostname = forwardedHost.replace(/:\d+$/, "")
            const isLocal =
                hostname === "localhost" ||
                hostname === "127.0.0.1" ||
                hostname.endsWith(".local")
            if (!isLocal) {
                url.protocol = "https:"
                url.hostname = hostname
                url.port = ""
                response.headers.set("location", url.toString())
            }
        } catch {
            // leave the original Location untouched on parse failure
        }
    }

    return response
}

export const config = {
    // The second entry also sends dotted program paths (`<id>.json`, `..%2F..`) to the
    // guard; the first skips every dotted path. Matchers must be literals: keep `vi|en`
    // equal to routing.locales.
    matcher: ["/((?!api|trpc|_next|_vercel|.*\\..*).*)", "/(vi|en)/programs/:path+"],
}
